class SwarmDecomposer:
    def __init__(self, agents, aggregator=None):
        self.agents = agents
        self.aggregator = aggregator or (lambda r: sum(r) / len(r))

    def decompose(self, task, max_depth=3):
        if max_depth == 0 or not self._requires_decomposition(task):
            return [(task, 1.0)]
        subtasks = self._llm_split(task)
        results = []
        for subtask, weight in subtasks:
            if self._is_atomic(subtask):
                result = self._execute_atomic(subtask)
            else:
                children = self.decompose(subtask, max_depth - 1)
                result = self._aggregate(children)
            results.append((result, weight))
        return self._weighted_aggregate(results)

    def _weighted_aggregate(self, results):
        total_weight = sum(w for _, w in results)
        return sum(r * w for r, w in results) / total_weight

swarm = SwarmDecomposer(agents=["agent1", "agent2"])
result = swarm.decompose("Build a full-stack app")
